 "content": "def transform(grid):
    out = [row[:] for row in grid]
    zeros = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 0]
    if not zeros:
        return out
    r0 = min(r for r, _ in zeros)
    r1 = max(r for r, _ in zeros)
    c0 = min(c for _, c in zeros)
    c1 = max(c for _, c in zeros)
    # The 2x2 zero marker creates full horizontal and vertical zero bands;
    # color 2 is the protected color and remains visible in those bands.
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if (r0 <= r <= r1 or c0 <= c <= c1) and grid[r][c] != 2:
                out[r][c] = 0
    return out
